using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace Overclock {
 sealed class SensorView:UserControl {
  readonly SensorClient client;readonly TreeView tree=new TreeView{Dock=DockStyle.Left,Width=200,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.None,FullRowSelect=true,HideSelection=false,ItemHeight=30,ShowLines=false};readonly DataGridView table=Theme.Grid("Sensor","Current","Minimum","Maximum","Unit");readonly SensorGraph graph=new SensorGraph{Dock=DockStyle.Bottom,Height=175,BackColor=Theme.Surface};readonly Timer timer=new Timer{Interval=1000};readonly TextBox search=new TextBox{Width=230,BackColor=Theme.Raised,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};bool updating;string filter="",shape="",selected;DateTime rendered;
  public SensorView(SensorClient c){client=c;Dock=DockStyle.Fill;BackColor=Theme.Background;var right=new Panel{Dock=DockStyle.Fill,Padding=new Padding(14,0,0,0)};right.Controls.Add(table);right.Controls.Add(graph);Controls.Add(right);Controls.Add(tree);var toolbar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=52,Padding=new Padding(0,5,0,5)};var caption=Theme.Label("FILTER SENSORS",9);caption.Size=new Size(120,30);caption.TextAlign=ContentAlignment.MiddleLeft;toolbar.Controls.Add(caption);toolbar.Controls.Add(search);var reset=Theme.Button("Reset min / max");reset.Click+=(s,e)=>client.Reset();toolbar.Controls.Add(reset);Controls.Add(toolbar);tree.AfterSelect+=(s,e)=>{filter=e.Node.Tag as string??"";rendered=DateTime.MinValue;RefreshData();};search.TextChanged+=(s,e)=>{rendered=DateTime.MinValue;RefreshData();};table.Columns[0].FillWeight=210;table.SelectionChanged+=(s,e)=>{if(updating||table.SelectedRows.Count==0)return;selected=table.SelectedRows[0].Tag as string;RefreshGraph();};timer.Tick+=(s,e)=>RefreshData();timer.Start();Disposed+=(s,e)=>timer.Dispose();RefreshData();}
  void RefreshData(){var snapshot=client.Snapshot;RefreshGraph();if(snapshot.Utc==rendered)return;rendered=snapshot.Utc;string signature=string.Join("|",snapshot.Sensors.Select(v=>v.Hardware+"/"+v.Type).Distinct().ToArray());if(shape!=signature){shape=signature;tree.BeginUpdate();tree.Nodes.Clear();var all=tree.Nodes.Add("All hardware");all.Tag="";foreach(var group in snapshot.Sensors.GroupBy(s=>s.Hardware)){var root=tree.Nodes.Add(group.Key);root.Tag=group.Key+"|";foreach(string type in group.Select(s=>s.Type).Distinct()){var n=root.Nodes.Add(type);n.Tag=group.Key+"|"+type;}}tree.ExpandAll();tree.EndUpdate();}string[] parts=filter.Split('|');string chosen=selected;int scroll=table.FirstDisplayedScrollingRowIndex;updating=true;table.Rows.Clear();foreach(var s in snapshot.Sensors.Where(v=>(filter==""||(v.Hardware==parts[0]&&(parts.Length<2||parts[1]==""||parts[1]==v.Type)))&&(search.Text==""||(v.Name+v.Hardware+v.Type).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0))){int i=table.Rows.Add(s.Name,F(s.Value),F(s.Min),F(s.Max),HardwareView.Unit(s.Type));table.Rows[i].Tag=s.Id;if(s.Id==chosen)table.Rows[i].Selected=true;}if(table.Rows.Count==0)table.Rows.Add(snapshot.Error??"No matching sensors","—","—","—","");selected=chosen;updating=false;if(scroll>=0&&scroll<table.Rows.Count)table.FirstDisplayedScrollingRowIndex=scroll;RefreshGraph();}
  static string F(float? v){return v.HasValue?v.Value.ToString("N1"):"—";}
  void RefreshGraph(){Queue<float> q;graph.Values=selected!=null&&client.History.TryGetValue(selected,out q)?q.ToArray():new float[0];var sensor=client.Snapshot.Sensors.FirstOrDefault(v=>v.Id==selected);graph.Title=sensor==null?"Select a sensor to explore its history":sensor.Name+" · "+HardwareView.Unit(sensor.Type)+" · last 300 samples";graph.Invalidate();}
 }
 sealed class SensorGraph:Control {
  public string Title;public float[] Values=new float[0];public SensorGraph(){DoubleBuffered=true;ForeColor=Theme.Text;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);TextRenderer.DrawText(e.Graphics,Title??"No history yet",Font,new Rectangle(16,12,Width-32,25),Theme.Muted,TextFormatFlags.EndEllipsis);if(Values.Length<2)return;float max=Values.Max(),min=Values.Min();if(max==min)max=min+1;using(var grid=new Pen(Theme.Line))for(int i=0;i<3;i++)e.Graphics.DrawLine(grid,16,48+i*(Height-76)/3,Width-16,48+i*(Height-76)/3);using(var pen=new Pen(Theme.Accent,2))for(int i=1;i<Values.Length;i++)e.Graphics.DrawLine(pen,16+(i-1)*(Width-32f)/(Values.Length-1),Height-25-(Values[i-1]-min)/(max-min)*(Height-76),16+i*(Width-32f)/(Values.Length-1),Height-25-(Values[i]-min)/(max-min)*(Height-76));TextRenderer.DrawText(e.Graphics,min.ToString("0.#")+" – "+max.ToString("0.#"),Font,new Point(16,Height-23),Theme.Muted);}
 }
}

